def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_c = op.count('C')
    opp_d = n - opp_c
    my_c = my.count('C')
    my_d = n - my_c
    last_my, last_op = history[-1]

    # Immediate retaliation if opponent just defected, but forgive if they've been cooperative.
    if last_op == 'D':
        if opp_c >= 2 and op[-2] == 'C':
            return 'C'
        if opp_d <= 2 and n < 20:
            return 'D'
        if opp_c * 2 < n:
            return 'D'
        return 'C'

    # If we've been too nice and opponent is heavily defecting, defect.
    if opp_d > opp_c + 2:
        return 'D'

    # Detect long mutual cooperation and occasionally test, but rarely.
    if n > 10 and opp_c == n and my_c == n:
        if rng.random() < 0.03:
            return 'D'
        return 'C'

    # Temptation check: if opponent has cooperated a lot recently, try a careful defection.
    recent = op[-10:] if n >= 10 else op
    recent_c = recent.count('C')
    if n >= 25 and recent_c >= 8 and opp_d <= 2:
        if rng.random() < 0.05:
            return 'D'
        return 'C'

    # If opponent appears mostly cooperative, cooperate.
    if opp_c >= opp_d:
        return 'C'

    # Otherwise, probe occasionally when losing.
    if rng.random() < 0.15:
        return 'D'
    return 'C'

